INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q647463', 'Battle of Artaxata', 'The Battle of Artaxata was fought near the Arsanias River in 68 BC between an army of the Roman Republic and the army of the Kingdom of Armenia. The Romans were led by proconsul Lucius Licinius Lucullus, while the Armenians were led by Tigranes II of Armenia, who was sheltering Mithridates VI of Pontus, his father-in-law and refugee King of Pontus.', -68, NULL, NULL, NULL, NULL, NULL, 'year', '68 BCE', 57, 'https://en.wikipedia.org/wiki/Battle_of_Artaxata'),
  ('Q2263382', 'Battle of Rhandeia', 'The Battle of Rhandeia, fought in the spring of 62 AD, was a military confrontation between combined Armenian-Parthian forces and the Roman Empire. The clash took place near Rhandeia, northeast of Melitene (modern-day Malatya in Turkey), with the Armenian troops led by Tiridates I and the Parthian forces commanded by Vologases I. The Roman force was commanded by Lucius Caesennius Paetus.', 62, NULL, NULL, NULL, NULL, NULL, 'year', '62', 45, 'https://en.wikipedia.org/wiki/Battle_of_Rhandeia'),
  ('Q20506839', 'Armenian Revolt', 'The Armenian Revolt (Arabic: ثَوْرَةُ الأَرْمَن) was an armed rebellion fought in 850–855 by Armenian nobility against Abbasid authority over Arminiya following a taxation dispute. The main leading families were the Bagratuni of Taron and Artsruni of Vaspurakan.', 850, NULL, NULL, 855, NULL, NULL, 'year', '850–855', 26, 'https://en.wikipedia.org/wiki/Armenian_Revolt_(850%E2%80%93855)'),
  ('Q2628015', 'Battle of Kapetron', 'The Battle of Kapetron or Kapetrou was fought between a Byzantine-Georgian army and the Seljuq Turks at the plain of Kapetron (modern Hasankale/Pasinler in northeastern Turkey) in 1048. The event was the culmination of a major raid led by the Seljuq prince Ibrahim Inal into Byzantine-ruled Armenia.', 1048, 9, 18, NULL, NULL, NULL, 'day', '18 September 1048', 55, 'https://en.wikipedia.org/wiki/Battle_of_Kapetron'),
  ('Q2916261', 'Battle of Garni', 'The Battle of Garni (Georgian: გარნისის ბრძოლა, Armenian: Գառնիի ճակատամարտ) was fought in 1225 near Garni, in modern day Armenia, then part of the Kingdom of Georgia. The invading Khwarazmian Empire was led by Jalal al-Din Mangburni, its last sultan, who had been driven from his realm by the Mongol Empire and was trying to recapture lost territories.', 1225, 8, NULL, NULL, NULL, NULL, 'month', 'August 1225', 53, 'https://en.wikipedia.org/wiki/Battle_of_Garni'),
  ('Q42005', 'Black Death', 'The Black Death was a plague pandemic that occurred in Europe from 1346 to 1353. It was one of the most fatal pandemics in human history, leading to the death of up to 50 million people, around 30% to 60% of the European population and approximately 33% of the Middle Eastern population.', 1346, NULL, NULL, 1352, NULL, NULL, 'year', '1346–1352', 92, 'https://en.wikipedia.org/wiki/Black_Death'),
  ('Q4551791', '1679 Armenia earthquake', 'The 1679 Armenia earthquake (also called Yerevan earthquake or Garni earthquake) took place on June 4 in the Yerevan region of Armenia, then part of the Safavid Iran. Numerous buildings were destroyed as a result of the earthquake.', 1679, 6, 4, NULL, NULL, NULL, 'day', '4 June 1679', 53, 'https://en.wikipedia.org/wiki/1679_Armenia_earthquake'),
  ('Q13053399', 'Battle of Halidzor', 'The Battle of Halidzor (Armenian: Հալիձորի ճակատամարտ) took place in the spring of 1727 at Halidzor Fortress, in what is now the Syunik region of Armenia, near the modern-day city of Kapan, between the Armenian forces under the leadership of David Bek and the Ottoman army.', 1727, 3, 26, 1727, 3, 7, 'day', '26 March 1727 – 7 March 1727', 43, 'https://en.wikipedia.org/wiki/Battle_of_Halidzor'),
  ('Q18162511', 'Battle of Yeghevārd', 'The Battle of Yeghevārd, also known as the Battle of Baghavard or Morad Tapeh or Arpachai or Echmiadzin, was the final major engagement of the Ottoman–Persian War of (1730–1735) where the principal Ottoman army in the Caucasus theatre under Koprulu Pasha''s command was utterly destroyed by only the advance guard of Nader''s army before the main Persian army could enter into the fray. The complete rout of Koprulu Pasha''s forces led to a number of besieged Ottoman strongholds in the theatre surrendering as any hope of relief proved ephemeral in light of the crushing defeat at Yeghevārd.', 1735, 6, 19, NULL, NULL, NULL, 'day', '19 June 1735', 45, 'https://en.wikipedia.org/wiki/Battle_of_Yeghev%C4%81rd'),
  ('Q16377676', 'Battle of Kirkhbulakh', 'The Battle of Kirkhbulakh (Georgian: ყირხბულახის ბრძოლა) was fought in 1751 in the village of Kirkhbulakh between the Kingdoms of Kartli and Kakheti commanded by Heraclius II against the Azad Khan Afghan''s armies, ending with Azad Khan Afghan''s army being defeated.', 1751, 7, 28, NULL, NULL, NULL, 'day', '28 July 1751', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kirkhbulakh'),
  ('Q48803703', 'Siege of Erivan', 'The siege of Erivan (Yerevan, the capital of modern Armenia) took place from July to September 1804, during the Russo-Persian War (1804–1813). After a difficult advance, the Russians under Pavel Tsitsianov besieged Erivan.', 1804, 7, NULL, 1804, 9, NULL, 'month', 'July 1804 – September 1804', 41, 'https://en.wikipedia.org/wiki/Siege_of_Erivan_(1804)'),
  ('Q48803831', 'Battle of Echmiadzin', 'The Battle of Echmiadzin took place in June 1804, during the Russo-Persian War of 1804–1813. A Russian force of 5,000 men under Pavel Tsitsianov advanced on Erivan.', 1804, NULL, NULL, NULL, NULL, NULL, 'year', '1804', 34, 'https://en.wikipedia.org/wiki/Battle_of_Echmiadzin_(1804)'),
  ('Q48804713', 'Siege of Erivan', 'The siege of Erivan took place in October and November 1808, during the Russo-Persian War of 1804–1813. As in 1804, the Iranians successfully defended the city and forced the Russians to withdraw.', 1808, NULL, NULL, 1808, 11, NULL, 'year', '1808', 34, 'https://en.wikipedia.org/wiki/Siege_of_Erivan_(1808)'),
  ('Q4110457', 'Capture of Erivan', 'The capture of Erivan (or Erevan/Yerevan; Persian: فتح ایروان, romanized: Fath e Iravān; Russian: Взятие Эривани, romanized: Vzyatie Ėrivani) took place on 1 October 1827, during the Russo-Persian War of 1826–1828. The city fell to the Russians after being besieged for a week and opened up the path for the eventual capture of Tabriz, the second largest city in Iran and an important trading post.', 1827, 10, 1, NULL, NULL, NULL, 'day', '1 October 1827', 48, 'https://en.wikipedia.org/wiki/Capture_of_Erivan'),
  ('Q4340762', 'Battle of Oshakan', 'The Battle of Oshakan (Armenian: Օշականի ճակատամարտ) was a battle that took place on 29 August 1827 during the Russo-Persian War (1826–1828) between the army of the heir to the Persian throne Abbas Mirza and the Russian detachment of Lieutenant General Afanasy Krasovsky. At the beginning of August 1827, the Persian army invaded Eastern Armenia, and, joining with the troops of sardar Husayn Khan Qajar of the Erivan Khanate, besieged the Etchmiadzin Monastery.', 1827, NULL, NULL, NULL, NULL, NULL, 'year', '1827', 39, 'https://en.wikipedia.org/wiki/Battle_of_Oshakan'),
  ('Q651391', 'Battle of Karakilisa', 'The Battle of Karakilisa (Armenian: Ղարաքիլիսայի ճակատամարտ Gharakilisayi chakatamart, Turkish: Karakilise Muharebesi or Karakilise Muharebeleri) took place during the Caucasus Campaign of World War I in the vicinity of Karakilisa (now Vanadzor), on May 25–28, 1918.', 1918, NULL, NULL, 1918, 5, 28, 'year', '1918', 55, 'https://en.wikipedia.org/wiki/Battle_of_Karakilisa'),
  ('Q762732', 'Battle of Sardarabad', 'The Battle of Sardarabad (Armenian: Սարդարապատի ճակատամարտ, romanized: Sardarapati chakatamart; Turkish: Serdarabad Muharebesi) was a battle of the Caucasus campaign of World War I that took place near Sardarabad, Armenia, from 21 to 29 May 1918, between the regular Armenian military units and militia on one side and the Ottoman army that had invaded Eastern Armenia on the other. As Sardarabad is approximately 40 kilometres (25 mi) west of the capital of Yerevan, the battle not only halted the Ottoman advance into the rest of Armenia, but also prevented the complete destruction of the…', 1918, 5, 22, 1918, 5, 29, 'day', '22 May 1918 – 29 May 1918', 66, 'https://en.wikipedia.org/wiki/Battle_of_Sardarabad'),
  ('Q791185', 'Battle of Abaran', 'The Battle of Bash Abaran (Armenian: Բաշ Աբարանի ճակատամարտ Bash Abarani chakatamart, Turkish: Baş-Abaran Muharebesi) was part of Caucasus Campaign of World War I that took place in the vicinity of Bash Abaran, in 1918. The Armenian victories at Bash Abaran, Sardarabad and Karakilisa, halted the Ottoman invasion of Eastern Armenia and were instrumental in allowing the formation of the short-lived First Republic of Armenia.', 1918, NULL, NULL, 1918, 5, 29, 'year', '1918', 60, 'https://en.wikipedia.org/wiki/Battle_of_Abaran'),
  ('Q1347812', 'Treaty of Alexandropol', 'The Treaty of Alexandropol (Armenian: Ալեքսանդրապոլի պայմանագիր; Turkish: Gümrü Anlaşması or "Gyumri Treaty") was a peace treaty between the First Republic of Armenia and the Grand National Assembly of Turkey. The treaty formally ended Turkey''s invasion of Armenia that had begun on 12 September 1920.', 1920, 12, 2, NULL, NULL, NULL, 'day', '2 December 1920', 62, 'https://en.wikipedia.org/wiki/Treaty_of_Alexandropol'),
  ('Q4819977', 'Battle of Alexandropol', 'The Battle of Alexandropol was a conflict between the First Republic of Armenia and the Turkish National Movement which was on November 7, 1920, at Alexandropol.', 1920, 11, 7, NULL, NULL, NULL, 'day', '7 November 1920', 39, 'https://en.wikipedia.org/wiki/Battle_of_Alexandropol'),
  ('Q5439864', 'February Uprising', 'The February Uprising (Armenian: Փետրվարյան ապստամբություն, romanized: P’etrvaryan apstambut’yun) was an anti-Bolshevik rebellion by the nationalist Armenian Revolutionary Federation which started on February 13 and was suppressed on April 2, 1921, by the recapture of Yerevan by Bolshevik forces.', 1921, 2, NULL, 1921, 4, NULL, 'month', 'February 1921 – April 1921', 48, 'https://en.wikipedia.org/wiki/February_Uprising'),
  ('Q381375', 'First Nagorno-Karabakh War', 'The First Nagorno-Karabakh War was an ethnic and territorial conflict that took place from February 1988 to May 1994 in the enclave of Nagorno-Karabakh in southwestern Azerbaijan between the majority ethnic Armenians of Nagorno-Karabakh backed by Armenia, and the Republic of Azerbaijan with support from Turkey. As the war progressed, Armenia and Azerbaijan, both former Soviet republics, entangled themselves in protracted, undeclared mountain warfare in the mountainous heights of Karabakh as Azerbaijan attempted to curb the Karabakh Movement.', 1988, 2, 20, 1994, 5, 16, 'day', '20 February 1988 – 16 May 1994', 80, 'https://en.wikipedia.org/wiki/First_Nagorno-Karabakh_War'),
  ('Q1975720', '1999 Armenian parliament shooting', 'The 1999 Armenian parliament shooting, commonly known in Armenia as October 27 (Armenian: Հոկտեմբերի 27, romanized: Hoktemberi k''sanyot), was an attack on the Armenian National Assembly in the capital of Yerevan on 27 October 1999 by a group of five armed men led by Nairi Hunanyan that, among others, killed the two de facto decision-makers in the country''s political leadership—Prime Minister Vazgen Sargsyan and Parliament Speaker Karen Demirchyan. Their reform-minded coalition had won a majority in a parliamentary election held in May of that year and had practically sidelined President…', 1999, 10, 27, NULL, NULL, NULL, 'day', '27 October 1999', 57, 'https://en.wikipedia.org/wiki/Armenian_parliament_shooting'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q264410', '2008 Armenian presidential election protests', 'A series of anti-government riots took place in Armenia following presidential elections held on 19 February 2008. Protests broke out in the Armenian capital Yerevan, organized by supporters of presidential candidate and former president Levon Ter-Petrosyan and other opposition leaders.', 2008, NULL, NULL, NULL, NULL, NULL, 'year', '2008', 41, 'https://en.wikipedia.org/wiki/2008_Armenian_presidential_election_protests'),
  ('Q4055393', 'Belavia Flight 1834', 'Belavia Flight 1834 was a scheduled international passenger flight from Yerevan, Armenia, to Minsk, Belarus, operated by Belavia. On the morning of 14 February 2008, the Bombardier Canadair Regional Jet carrying 18 passengers and three crew crashed and burst into flames shortly after takeoff from Zvartnots International Airport near Yerevan, the capital of Armenia.', 2008, 2, 14, NULL, NULL, NULL, 'day', '14 February 2008', 51, 'https://en.wikipedia.org/wiki/Belavia_Flight_1834'),
  ('Q20512994', 'Zurich Protocols', 'The Zurich Protocols were two bilateral protocols signed in 2009 by Armenia and Turkey that envisioned starting the process of normalizing relations between the two countries. The Protocols included provisions for the establishment of formal diplomatic relations, the opening of the Turkish-Armenian border (which has been closed since 1993), and the establishment of a joint historical commission on the Armenian genocide issue.', 2009, 10, 10, NULL, NULL, NULL, 'day', '10 October 2009', 47, 'https://en.wikipedia.org/wiki/Zurich_Protocols'),
  ('Q189079', 'Van earthquake of 2011', 'The 2011 Van earthquakes occurred in eastern Turkey near the city of Van. The first earthquake happened on 23 October at 13:41 local time.', 2011, 10, 23, NULL, NULL, NULL, 'day', '23 October 2011', 70, 'https://en.wikipedia.org/wiki/2011_Van_earthquakes'),
  ('Q18758263', 'Gyumri massacre', 'The Gyumri massacre was a mass murder of seven members of the Armenian Avetisyan family in Gyumri, Armenia, on January 12, 2015. The suspect, Valery Permyakov, a Russian serviceman from the Russian 102nd Military Base, was apprehended by the Armenia-based Russian Border Guards near the border with Turkey and brought into custody at the Gyumri base for further investigation under the Russian jurisdiction.', 2015, 1, 12, NULL, NULL, NULL, 'day', '12 January 2015', 53, 'https://en.wikipedia.org/wiki/Gyumri_massacre'),
  ('Q23688698', '2016 Nagorno-Karabakh conflict', 'The 2016 Nagorno-Karabakh conflict, also known as the Four-Day War, April War, or April clashes, began along the former Nagorno-Karabakh line of contact on 1 April 2016 with the Artsakh Defence Army, backed by the Armenian Armed Forces, on one side and the Azerbaijani Armed Forces on the other. The clashes occurred in a region that is disputed between the self-proclaimed Republic of Artsakh and the Republic of Azerbaijan.', 2016, 4, 2, 2016, 4, 5, 'day', '2 April 2016 – 5 April 2016', 65, 'https://en.wikipedia.org/wiki/2016_Nagorno-Karabakh_conflict'),
  ('Q51846024', '2018 Armenian Revolution', 'The 2018 Armenian Revolution, most commonly known in Armenia as #MerzhirSerzhin (Armenian: #ՄերժիրՍերժին, lit. ''#RejectSerzh''), was a series of anti-government protests in Armenia from April to May 2018 staged by various political and civil groups led by a member of the Armenian parliament – Nikol Pashinyan (head of the Civil Contract party). Protests and marches took place initially in response to Serzh Sargsyan''s third consecutive term as the most powerful figure in the government of Armenia, later broadening against the ruling Republican Party, who were in power since 1999.', 2018, 5, 8, 2018, 5, 8, 'day', '8 May 2018', 67, 'https://en.wikipedia.org/wiki/2018_Armenian_Revolution'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q97303396', 'July 2020 Armenian–Azerbaijani clashes', 'The July 2020 Armenian–Azerbaijani clashes began on 12 July 2020 between the Armenian Armed Forces and Azerbaijani Armed Forces. Initial clashes occurred near Movses in Tavush Province of Armenia, and Ağdam in Tovuz District of Azerbaijan at the Armenian–Azerbaijani state border.', 2020, 7, 12, 2020, 7, NULL, 'day', '12 July 2020 – July 2020', 60, 'https://en.wikipedia.org/wiki/July_2020_Armenian%E2%80%93Azerbaijani_clashes'),
  ('Q99659280', 'Second Nagorno-Karabakh War', 'The Second Nagorno-Karabakh War was an armed conflict in 2020 that took place in the disputed region of Nagorno-Karabakh and the surrounding occupied territories. It was a major escalation of an unresolved conflict over the region, involving Azerbaijan, Armenia and the self-declared Armenian breakaway state of Artsakh.', 2020, NULL, NULL, 2020, 11, 10, 'year', '2020', 81, 'https://en.wikipedia.org/wiki/Second_Nagorno-Karabakh_War'),
  ('Q101305942', 'Battle of Shusha', 'The Battle of Shusha (Azerbaijani: Şuşa döyüşü or Şuşa uğrunda döyüş; Armenian: Շուշիի ճակատամարտ, romanized: Shushii chakatamart) was the final and decisive battle of the Second Nagorno-Karabakh War, fought between the armed forces of Azerbaijan and the self-proclaimed Republic of Artsakh, militarily supported by Armenia, over the control of the city of Shusha. The battle is considered one of the bloodiest battles of the war.', 2020, 11, NULL, NULL, NULL, NULL, 'month', 'November 2020', 60, 'https://en.wikipedia.org/wiki/Battle_of_Shusha_(2020)'),
  ('Q101429497', '2020 Nagorno-Karabakh ceasefire agreement', 'The 2020 Nagorno-Karabakh ceasefire agreement was an armistice agreement that ended the Second Nagorno-Karabakh War. It was signed on 9 November by the President of Azerbaijan Ilham Aliyev, the Prime Minister of Armenia Nikol Pashinyan and the President of Russia Vladimir Putin, and ended all hostilities in the Nagorno-Karabakh region from 00:00, on 10 November 2020 Moscow time.', 2020, 11, 9, NULL, NULL, NULL, 'day', '9 November 2020', 69, 'https://en.wikipedia.org/wiki/2020_Nagorno-Karabakh_ceasefire_agreement'),
  ('Q101436761', '2020−2021 Armenian protests', 'The 2020−2021 Armenian protests (also known as the March of Dignity; Armenian: Արժանապատվության երթ, romanized: Arzhanapatvut''yan yert'') were a series of protests that began following the Nagorno-Karabakh ceasefire agreement on 10 November 2020. After Prime Minister Nikol Pashinyan announced that he signed an agreement to cede Armenian-occupied territories in Azerbaijan and put an end to six weeks of hostilities over the Nagorno-Karabakh region, thousands of people took to the streets, and hundreds stormed the Parliament building in the capital Yerevan.', 2020, 11, 10, 2021, 4, 25, 'day', '10 November 2020 – 25 April 2021', 57, 'https://en.wikipedia.org/wiki/2020%E2%80%932021_Armenian_protests'),
  ('Q113404565', 'August 2022 Nagorno-Karabakh clashes', 'The military forces of Armenia and Azerbaijan have been engaged in a border conflict since 12 May 2021, when Azerbaijani soldiers crossed several kilometers into Armenia in the provinces of Syunik and Gegharkunik. Despite international calls for withdrawal from the European Parliament, France, Iran, and the United States, Azerbaijan has maintained its presence on Armenian soil, occupying at least 215 square kilometers (83 sq mi) of internationally recognized Armenian territory.', 2022, 8, 3, NULL, NULL, NULL, 'day', '3 August 2022', 37, 'https://en.wikipedia.org/wiki/August_2022_Nagorno-Karabakh_clashes'),
  ('Q113514937', '2022 Yerevan explosion', 'On 14 August 2022, at 13:23 local time, a large explosion took place in the Surmalu shopping centre in the Armenian capital of Yerevan. It caused widespread destruction and fire, leaving dozens of dead and injured.', 2022, 8, 14, NULL, NULL, NULL, 'day', '14 August 2022', 48, 'https://en.wikipedia.org/wiki/2022_Yerevan_explosion'),
  ('Q133821305', 'Armenia-Azerbaijan peace agreement', 'The Armenia–Azerbaijan peace deal, officially titled the Agreement "On the Establishment of Peace and Interstate Relations between the Republic of Armenia and the Republic of Azerbaijan", aims to end the ongoing Nagorno-Karabakh conflict between Armenia and Azerbaijan. On 8 August 2025, Armenian prime minister Nikol Pashinyan and Azerbaijani president Ilham Aliyev, with the mediation of United States president Donald Trump, initialed an agreement and signed a joint declaration emphasizing the need to continue efforts toward the signing and final ratification of the agreement.', 2025, 8, 8, NULL, NULL, NULL, 'day', '8 August 2025', 63, 'https://en.wikipedia.org/wiki/Armenia%E2%80%93Azerbaijan_peace_agreement');
